/**
 * signup-authorizer — HTTP API Lambda authorizer for the registration API
 * (`POST /signup`, `POST /signup/resend-invitation`).
 *
 * Design doc 1.4 and 3.1 item 2: the API key AND the source-IP allowlist
 * both live in Secrets Manager, and the allowed org is derived from the
 * key, never from the request. Implementation plan W6.
 *
 * Secret `apersona/signup/apikey` (SIGNUP_SECRET_ID) is JSON:
 *   { "keys": [ { "id": "launch", "key": "<secret>", "orgId": "apersona",
 *                 "allowedIps": ["203.0.113.7/32", "198.51.100.0/24"] } ] }
 * One entry per caller. Phase 2 (IT Svc Org keys) adds entries with a
 * different orgId; nothing here changes.
 *
 * Response is the HTTP API SIMPLE format. API Gateway maps:
 *   identity source (X-Api-Key) missing  -> 401 without invoking us
 *   isAuthorized: false                  -> 403
 * so a wrong key and a disallowed IP both surface as 403 (see design doc
 * 3.2 note). Authorizer result caching is disabled on the route (CDK) and
 * the secret is read on every invocation (no warm-start cache), so a
 * revoked key or IP takes effect on the next request, as 3.2 promises.
 * Signup volume is a handful of requests a day; one GetSecretValue per
 * request is cheaper than a stale allowlist.
 *
 * Fail closed: any error (secret unreadable, malformed JSON, no IP in the
 * event) denies. The key value is never logged.
 */

import { createHash, timingSafeEqual } from "node:crypto";
import { BlockList, isIP } from "node:net";
import {
  SecretsManagerClient,
  GetSecretValueCommand,
} from "@aws-sdk/client-secrets-manager";

const DEFAULT_SECRET_ID = "apersona/signup/apikey";

const secretsManager = new SecretsManagerClient({ region: process.env.AWS_REGION });

const log = (level, message, extra = {}) =>
  console.log(JSON.stringify({ timestamp: new Date().toISOString(), level, service: "signup-authorizer", message, ...extra }));

/** Parse one secret entry into a comparable shape; drop anything unusable. */
function compileKey(entry, idx) {
  if (!entry || typeof entry.key !== "string" || !entry.key || typeof entry.orgId !== "string" || !entry.orgId) {
    log("WARN", "secret entry skipped: missing key or orgId", { index: idx });
    return null;
  }
  const ips = Array.isArray(entry.allowedIps) ? entry.allowedIps : [];
  const allow = new BlockList();
  let count = 0;
  for (const spec of ips) {
    const [addr, prefix] = String(spec).split("/");
    const family = isIP(addr) === 6 ? "ipv6" : isIP(addr) === 4 ? "ipv4" : null;
    if (!family) { log("WARN", "allowedIps entry skipped: not an IP", { index: idx, spec }); continue; }
    if (prefix === undefined) allow.addAddress(addr, family);
    else allow.addSubnet(addr, Number(prefix), family);
    count++;
  }
  if (count === 0) {
    // 1.4: key AND allowlist. A key with no usable IPs can never authorize.
    log("WARN", "secret entry has no usable allowedIps; it will never authorize", { index: idx, id: entry.id });
  }
  return {
    id: String(entry.id ?? idx),
    orgId: entry.orgId,
    keyHash: createHash("sha256").update(entry.key).digest(),
    allow,
    ipCount: count,
  };
}

export async function loadKeys() {
  const res = await secretsManager.send(
    new GetSecretValueCommand({ SecretId: process.env.SIGNUP_SECRET_ID || DEFAULT_SECRET_ID })
  );
  const parsed = JSON.parse(res.SecretString || "");
  const list = Array.isArray(parsed?.keys) ? parsed.keys : [];
  return list.map(compileKey).filter(Boolean);
}

/** Constant-time match on sha256 digests (equal length by construction). */
function matchKey(keys, presented) {
  const h = createHash("sha256").update(presented).digest();
  let found = null;
  for (const k of keys) {
    // Compare every entry so timing does not reveal which index matched.
    if (timingSafeEqual(k.keyHash, h) && !found) found = k;
  }
  return found;
}

function headerValue(headers, name) {
  if (!headers) return undefined;
  const want = name.toLowerCase();
  for (const [k, v] of Object.entries(headers)) if (k.toLowerCase() === want) return v;
  return undefined;
}

export const handler = async (event) => {
  const deny = (reason, extra = {}) => {
    log("WARN", "denied", { reason, ...extra });
    return { isAuthorized: false, context: {} };
  };
  try {
    const presented = headerValue(event.headers, "x-api-key");
    if (typeof presented !== "string" || !presented) return deny("missing_api_key");

    const sourceIp = event.requestContext?.http?.sourceIp;
    if (!sourceIp || !isIP(sourceIp)) return deny("no_source_ip");

    const keys = await loadKeys();
    const key = matchKey(keys, presented);
    if (!key) return deny("bad_api_key", { sourceIp });

    if (!key.allow.check(sourceIp, isIP(sourceIp) === 6 ? "ipv6" : "ipv4")) {
      return deny("ip_not_allowed", { sourceIp, apiKeyId: key.id });
    }

    log("INFO", "authorized", { apiKeyId: key.id, orgId: key.orgId, sourceIp });
    return { isAuthorized: true, context: { apiKeyId: key.id, orgId: key.orgId } };
  } catch (err) {
    return deny("error", { cause: err?.name || String(err) });
  }
};
